head.script:
scwin.eventLog = [];
scwin.cancelWindowList = false;

scwin.onpageload = function() {
    windowContainer1.createWindow("win1", null, "windowContainer_useWindowScrollButton_WAEA-882_sub.xml", "Window 1", "win1", "existWindow");
    windowContainer1.createWindow("win2", null, "windowContainer_useWindowScrollButton_WAEA-882_sub.xml", "Window 2", "win2", "existWindow");
};

scwin.windowContainer1_onbeforewindowscrollbuttonclick = function() {
    scwin.eventLog.push({
        index: scwin.eventLog.length + 1		
    });
	console.log("onbeforewindowscrollbuttonclick", scwin.eventLog.length);
    if (scwin.cancelWindowList) {
        return false;
    }
};
